function requestPersistence(){try{navigator.storage?.persist?.().catch(()=>{})}catch{}}
function refreshAccountBadge(){const label=$('accountSwitchName');if(label)label.textContent=account?.name||'Tài khoản';const count=$('accountSwitchCount');if(count)count.textContent=identityRegistry.size+' TK';}
function onboarding(show){$('accountOnboarding').hidden=!show;document.querySelector('.app').hidden=show;if(show){$('onboardRecovery').focus();}else{refreshAccountBadge();}}
function switchRisk(){return !!call||sessions.size>0||pending.size>0}
