async function accountAction(fn){if(identityBusy)return;identityBusy=true;try{return await accountLock(fn)}finally{identityBusy=false}}
async function activateAccount(id){if(account?.id===id){dismiss();return}if(!allowSwitch())return;await accountAction(async()=>{await refreshIdentities();const a=identityRegistry.get(id);if(!a)throw Error('Không tìm thấy tài khoản trên thiết bị');await useIdentity(await loadIdentity(a));dismiss();toast('Đã chuyển sang '+account.name)})}
