function newAccountView(first=false){const body=modal('Tạo tài khoản mới','NEW IDENTITY'),name=el('input');name.maxLength=48;name.placeholder='Tên hiển thị (tùy chọn)';const field=el('label','field','Tên tài khoản');field.append(name);body.append(text(first?'Caller sẽ tạo một danh tính mới. Nếu từng dùng Caller ở nơi khác, hãy chọn khôi phục tài khoản để không bị trùng.':'Tạo thêm một danh tính riêng, với danh bạ và lịch sử độc lập. Tài khoản hiện tại vẫn được lưu.'),field,row(button('Tạo tài khoản',()=>createLocalAccount(name.value,first),'btn primary','plus'),button('Hủy',dismiss)))}
async function accountManager(){await refreshIdentities();refreshAccountBadge();const body=modal('Tài khoản trên thiết bị','ACCOUNT SWITCHER');body.append(text('Các tài khoản dưới đây đã được lưu trên môi trường ứng dụng này. Bạn có thể chuyển đổi mà không cần nhập lại mã khôi phục.'));const list=el('div','account-list');for(const a of [...identityRegistry.values()].sort((x,y)=>Number(y.id===account?.id)-Number(x.id===account?.id)||(y.updatedAt||0)-(x.updatedAt||0))){const current=a.id===account?.id,b=el('button','account-item'+(current?' current':'')),wrap=el('span','minw');b.type='button';wrap.append(el('strong','',a.name),el('small','',short(a.id)));b.append(el('span','avatar',initials(a.name)),wrap,el('span','account-state',current?'Đang dùng':'Chuyển ›'));b.addEventListener('click',safe(()=>activateAccount(a.id)));list.append(b)}body.append(list,option('plus','Thêm tài khoản mới','Tạo một danh tính độc lập trên thiết bị.',()=>newAccountView(false)),option('scan','Thêm tài khoản đã có','Quét QR hoặc dán mã khôi phục của bạn.',()=>scannerView('Khôi phục tài khoản',restore)),text('Mã thiết bị: '+(deviceId?deviceId.slice(0,8):'—')+' · Chỉ định danh môi trường cài đặt, không phải mã phần cứng.'));if(account)body.append(button('Cài đặt tài khoản hiện tại',showProfile,'btn primary','user'))}
