const short=id=>id? id.slice(0,6)+' · '+id.slice(6,12):'';
const initials=n=>String(n||'?').trim().split(/\s+/).slice(-2).map(x=>Array.from(x)[0]).join('').toUpperCase().slice(0,2)||'?';
const pub=k=>({kty:'EC',crv:'P-256',x:k.x,y:k.y});
async function fingerprint(p){if(p?.kty!=='EC'||p.crv!=='P-256'||typeof p.x!=='string'||p.x.length!==43||typeof p.y!=='string'||p.y.length!==43)throw Error('Khóa công khai không hợp lệ');return b64(new Uint8Array(await crypto.subtle.digest('SHA-256',enc.encode(p.x+'.'+p.y))));}
