function wire(s,dc){s.dc=dc;dc.addEventListener('open',()=>{if(s.closed||s.owner!==account?.id||!s.remote){closeSession(s);return}s.authenticated=true;clearTimeout(s.waitTimer);logNetwork(s,'Đã kết nối P2P');pending.delete(s.sid);const old=sessions.get(s.remote.id);if(old&&old!==s)closeSession(old);sessions.set(s.remote.id,s);if(s.purpose==='chat'){upsert(s.remote);select(s.remote.id);flush(s);toast('Đã kết nối '+s.remote.name)}else{toast('Đã kết nối thiết bị · Đang đồng bộ');syncOut(s).catch(e=>toast(e.message,true))}render();if($('modal').open)dismiss()});s.rx=Promise.resolve();dc.bufferedAmountLowThreshold=300000;dc.addEventListener('bufferedamountlow',()=>{if(s.authenticated&&s.purpose==='chat')flush(s)});dc.addEventListener('message',e=>{if(typeof e.data!=='string'||e.data.length>60000||!s.authenticated)return;s.rx=s.rx.then(()=>onPacket(s,JSON.parse(e.data))).catch(err=>{console.error(err);toast('Không thể xử lý dữ liệu từ peer.',true)})});dc.addEventListener('close',()=>closeSession(s));dc.addEventListener('error',()=>{toast('Kênh dữ liệu bị lỗi',true);closeSession(s)})}
function captureTrans(s){for(const t of s.pc.getTransceivers()){const kind=t.receiver.track.kind;if(kind==='audio'||kind==='video')s.trans[kind]=t}}
function validSdp(d,type){if(d?.type!==type||typeof d.sdp!=='string'||d.sdp.length>45000||!d.sdp.startsWith('v=0'))throw Error('SDP không hợp lệ');if(!/a=candidate:/.test(d.sdp))throw Error('QR bên kia không có địa chỉ ICE; hãy tạo lại kết nối.');return d}
async function startOffer(target,purpose){if(busy||identityBusy||!account)return;busy=true;const sid=uid(),s=makeSession(sid,purpose,target||null);pending.set(sid,s);try{const body=modal('Đang tạo kết nối','ICE GATHERING');body.append(text('Đang thu thập địa chỉ mạng bằng WebRTC…'));if(purpose==='chat'){s.trans.audio=s.pc.addTransceiver('audio',{direction:'sendrecv'});s.trans.video=s.pc.addTransceiver('video',{direction:'sendrecv'})}wire(s,s.pc.createDataChannel('caller',{ordered:true}));await s.pc.setLocalDescription(await s.pc.createOffer());await gather(s.pc);pendingStatus(s,'Đã tạo QR offer');const code=await envelope('offer',{sid,purpose,to:purpose==='sync'?account.id:target?.id||null,expires:now()+600000,desc:s.pc.localDescription.toJSON()});s.offerCode=code;s.expires=now()+600000;qrView('1 · QR kết nối','B quét QR này rồi tạo QR phản hồi. A quét QR phản hồi. Giữ cả hai ứng dụng mở. '+candidateLabel(candidateCounts(s.pc.localDescription)),code,[button('2 · Quét QR phản hồi',()=>scannerView('Quét QR phản hồi'),'btn primary','scan')]);}catch(e){closeSession(s);dismiss();throw e}finally{busy=false}}
async function handleCode(code){const owner=account?.id;if(!owner||identityBusy)throw Error('Hãy chọn tài khoản trước');if(code.startsWith('CALLER-KEY1.'))throw Error('Đây là mã bí mật. Dùng chức năng Khôi phục tài khoản.');const o=await parse(code);if(owner!==account?.id||identityBusy)throw Error('Tài khoản đã thay đổi; hãy quét lại mã.');if(o.type==='contact'){if(o.from.id===account.id)throw Error('Đây là QR của chính bạn');upsert(o.from);select(o.from.id);const b=modal('Đã thêm '+o.from.name,'BẠN BÈ');b.append(text('QR danh tính chỉ lưu bạn vào danh bạ, chưa mở được đường truyền. Tạo QR kết nối, bên kia quét và trả QR phản hồi.'),row(button('Tạo QR kết nối',()=>startOffer(o.from,'chat'),'btn primary'),button('Để sau',dismiss)));return}if(!['offer','answer'].includes(o.type)||typeof o.sid!=='string'||o.sid.length>64||!['chat','sync'].includes(o.purpose)||!Number.isFinite(o.expires)||o.expires<now()||o.expires>now()+900000)throw Error('Mã kết nối không hợp lệ hoặc hết hạn');if(o.to&&o.to!==account.id)throw Error('Mã dành cho thiết bị khác');if((o.purpose==='sync')!==(o.from.id===account.id))throw Error('Không đúng loại danh tính cho kết nối');if(o.type==='offer'){if(pending.has(o.sid))throw Error('QR này đã được xử lý; hãy sử dụng QR phản hồi đang mở hoặc tạo phiên mới.');if(busy)throw Error('Đang tạo một kết nối khác');busy=true;let s;try{validSdp(o.desc,'offer');s=makeSession(o.sid,o.purpose,o.from);pending.set(s.sid,s);const body=modal('Đang tạo QR phản hồi','ICE GATHERING');body.append(text('Đang tạo answer và thu thập ICE…'));await s.pc.setRemoteDescription(o.desc);captureTrans(s);for(const t of Object.values(s.trans))t.direction='sendrecv';await s.pc.setLocalDescription(await s.pc.createAnswer());await gather(s.pc);pendingStatus(s,'Đã tạo QR answer');const answer=await envelope('answer',{sid:o.sid,purpose:o.purpose,to:o.from.id,expires:Math.min(o.expires,now()+600000),desc:s.pc.localDescription.toJSON()});if(o.purpose==='chat'){upsert(o.from);select(o.from.id)}qrView('2 · QR phản hồi','A quét QR phản hồi này; sau đó cả hai chờ kết nối. '+candidateLabel(candidateCounts(s.pc.localDescription)),answer);}catch(e){if(s)closeSession(s);throw e}finally{busy=false};return}
const s=pending.get(o.sid);if(!s||s.pc.signalingState!=='have-local-offer'||s.purpose!==o.purpose||s.expires<now())throw Error('Không tìm thấy offer đang chờ. Tạo kết nối lại.');if(s.remote&&s.remote.id!==o.from.id)throw Error('QR phản hồi từ sai người');s.remote=o.from;validSdp(o.desc,'answer');await s.pc.setRemoteDescription(o.desc);if(s.closed||s.owner!==account?.id)return;pendingStatus(s,'Đã nhận QR phản hồi · đang ICE');connectionWait(s);captureTrans(s);if(o.purpose==='chat'){upsert(o.from);select(o.from.id)}dismiss();toast('Đang thiết lập kết nối trực tiếp...')}
function addMessage(peer,msg){const arr=db.messages[peer]??=[];if(arr.some(x=>x.id===msg.id))return false;arr.push(msg);arr.sort((a,b)=>a.ts-b.ts||a.id.localeCompare(b.id));save();return true}
function validMessage(m,peer){return m&&typeof m.id==='string'&&m.id.length<=80&&typeof m.body==='string'&&m.body.length<=12000&&m.body.length>0&&Number.isFinite(m.ts)&&Math.abs(m.ts)<8.64e15&&[account.id,peer].includes(m.from)&&typeof m.delivered==='boolean'}
function flush(s){if(!s.remote||s.purpose!=='chat')return;for(const m of db.messages[s.remote.id]||[])if(m.from===account.id&&!m.delivered){if(!send(s,{t:'msg',id:m.id,body:m.body,ts:m.ts}))break}}
async function waitDrain(s){while(s.dc?.readyState==='open'&&s.dc.bufferedAmount>300000)await new Promise(r=>setTimeout(r,70));if(s.dc?.readyState!=='open')throw Error('Kết nối đồng bộ đã đóng')}
async function syncOut(s){if(s.owner!==account?.id||s.closed)return;const syncDB=db;for(const p of Object.values(syncDB.contacts)){await waitDrain(s);if(!send(s,{t:'sync-contact',profile:p}))throw Error('Không gửi được dữ liệu đồng bộ');for(const m of syncDB.messages[p.id]||[]){await waitDrain(s);if(!send(s,{t:'sync-message',peer:p.id,message:m}))throw Error('Không gửi được lịch sử')}}send(s,{t:'sync-done'})}
async function onPacket(s,o){if(s.closed||s.owner!==account?.id||!o||typeof o.t!=='string')return;const peer=s.remote.id;if(s.purpose==='sync'){if(peer!==account.id)return;if(o.t==='sync-contact'){const p=await validateProfile(o.profile);if(s.closed||s.owner!==account?.id)return;upsert(p)}else if(o.t==='sync-message'&&db.contacts[o.peer]&&validMessage(o.message,o.peer)){const m=o.message,old=db.messages[o.peer]?.find(x=>x.id===m.id);if(old&&m.delivered&&!old.delivered){old.delivered=true;save()}else addMessage(o.peer,m)}else if(o.t==='sync-done')toast('Đã nhận đồng bộ danh bạ và lịch sử');render();return}
if(o.t==='msg'){const m={id:o.id,body:o.body,ts:o.ts,from:peer,delivered:true};if(!validMessage(m,peer))return;const isNew=addMessage(peer,m);send(s,{t:'ack',id:m.id});render();if(isNew&&active!==peer)toast('Tin nhắn mới từ '+s.remote.name);return}
if(o.t==='ack'){const m=db.messages[peer]?.find(x=>x.id===o.id&&x.from===account.id);if(m){m.delivered=true;save();render()}return}
if(o.t==='call-invite'){if(typeof o.id!=='string'||o.id.length>80||!['voice','video'].includes(o.mode))return;if(call){send(s,{t:'call-reject',id:o.id});return}call={s,id:o.id,mode:o.mode,state:'incoming',stream:null};const b=modal('Cuộc gọi '+(o.mode==='video'?'video':'thoại'),'INCOMING CALL');b.append(text(s.remote.name+' đang gọi cho bạn.'),row(button('Từ chối',()=>{send(s,{t:'call-reject',id:o.id});call=null;dismiss()}),button('Chấp nhận',()=>acceptCall(),'btn primary','phone')));return}
if(!call||call.s!==s||call.id!==o.id)return;if(o.t==='call-accept'&&call.state==='outgoing'){try{await attachMedia(call);call.state='active';updateCallView()}catch(e){endCall(true);throw e}}else if(o.t==='call-reject'||o.t==='call-end'){if(call.state==='incoming')dismiss();endCall(false);toast(o.t==='call-reject'?'Cuộc gọi bị từ chối':'Cuộc gọi đã kết thúc')}}
$('composer').addEventListener('submit',e=>{e.preventDefault();const body=$('message').value.trim();if(!active||!body)return;const m={id:uid(),body,ts:now(),from:account.id,delivered:false};addMessage(active,m);$('message').value='';storeDraft();const s=connected(active);if(s)flush(s);render();$('messages').scrollTop=$('messages').scrollHeight});
async function mediaFor(mode){try{return await navigator.mediaDevices.getUserMedia({audio:true,video:mode==='video'?{facingMode:'user',width:{ideal:960},height:{ideal:540}}:false})}catch{throw Error('Không thể sử dụng mic/camera. Hãy cấp quyền trong trình duyệt.')}}
async function attachMedia(c){captureTrans(c.s);for(const kind of ['audio','video']){const t=c.s.trans[kind],track=c.stream?.getTracks().find(x=>x.kind===kind)||null;if(!t&&track)throw Error('Kênh media không được thiết lập');if(t)await t.sender.replaceTrack(track)}}
function updateCallView(){if(!call)return;const c=call;if(c.state==='active'&&!c.startedAt)c.startedAt=now();updateCallDuration();if(!callClock)callClock=setInterval(updateCallDuration,1000);$('callOverlay').hidden=false;$('callName').textContent=c.s.remote.name;$('callAvatar').textContent=initials(c.s.remote.name);$('callAvatar').dataset.tone=tone(c.s.remote.id);$('callStatus').textContent=c.state==='active'?'Đã kết nối · WebRTC':c.state==='outgoing'?'Đang gọi...':'Đang kết nối...';$('remoteVideo').srcObject=c.s.remoteStream;if(c.stream)$('localVideo').srcObject=c.stream;$('localVideo').hidden=c.mode!=='video';$('camera').hidden=c.mode!=='video';$('camera').classList.toggle('off',!c.stream?.getVideoTracks()[0]?.enabled);$('mute').classList.toggle('off',!c.stream?.getAudioTracks()[0]?.enabled);document.querySelector('.media-area').classList.toggle('video-live',c.mode==='video'&&c.state==='active'&&c.s.remoteStream.getVideoTracks().some(t=>!t.muted));$('remoteVideo').play().catch(()=>{})}
async function startCall(mode){const s=connected(active);if(!s)throw Error('Hãy kết nối QR trước');if(call)throw Error('Đang có cuộc gọi');const c={s,id:uid(),mode,state:'outgoing',stream:null};call=c;try{c.stream=await mediaFor(mode);if(call!==c){c.stream.getTracks().forEach(t=>t.stop());return}if(!send(s,{t:'call-invite',id:c.id,mode}))throw Error('Không gửi được lời mời');updateCallView();setTimeout(()=>{if(call===c&&c.state==='outgoing'){endCall(true);toast('Không có phản hồi')}},45000)}catch(e){if(call===c)endCall(false);throw e}}
async function acceptCall(){const c=call;if(!c||c.state!=='incoming')return;c.state='connecting';dismiss();try{c.stream=await mediaFor(c.mode);if(call!==c){c.stream.getTracks().forEach(t=>t.stop());return}await attachMedia(c);if(!send(c.s,{t:'call-accept',id:c.id}))throw Error('Kết nối đã đóng');c.state='active';updateCallView()}catch(e){endCall(true);throw e}}
function updateCallDuration(){const e=$('callDuration');if(!call?.startedAt){e.hidden=true;return}const seconds=Math.max(0,Math.floor((now()-call.startedAt)/1000));e.hidden=false;e.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')}
function endCall(notify=true){if(!call)return;clearInterval(callClock);callClock=null;$('callDuration').hidden=true;const c=call;call=null;if(notify)send(c.s,{t:'call-end',id:c.id});for(const t of Object.values(c.s.trans))t.sender.replaceTrack(null).catch(()=>{});c.stream?.getTracks().forEach(t=>t.stop());$('localVideo').srcObject=null;$('remoteVideo').srcObject=null;$('callOverlay').hidden=true}
$('modal').addEventListener('close',()=>{if(call?.state==='incoming'){send(call.s,{t:'call-reject',id:call.id});call=null}});
$('hangup').addEventListener('click',()=>endCall(true));$('mute').addEventListener('click',()=>{const t=call?.stream?.getAudioTracks()[0];if(t){t.enabled=!t.enabled;updateCallView()}});$('camera').addEventListener('click',()=>{const t=call?.stream?.getVideoTracks()[0];if(t){t.enabled=!t.enabled;updateCallView()}});$('remoteVideo').addEventListener('click',()=> $('remoteVideo').play().catch(()=>{}));
