async function init(){if(!isSecureContext||!crypto.subtle||!window.RTCPeerConnection)throw Error('Caller yêu cầu HTTPS và trình duyệt hỗ trợ WebRTC.');await accountLock(async()=>{await refreshIdentities();await initDevice();const meta=await idbRequest('meta','readonly',store=>store.get('active'));const pref=localRead(ACTIVE_KEY)||meta.value||localRead('caller.account.v1')?.id;const records=[...identityRegistry.values()].sort((a,b)=>Number(b.id===pref)-Number(a.id===pref)||(b.updatedAt||0)-(a.updatedAt||0));for(const record of records){try{await useIdentity(await loadIdentity(record));return}catch(e){console.warn('Không mở được danh tính đã lưu',e)}}onboarding(true);if(records.length)toast('Không mở được tài khoản cũ. Hãy khôi phục bằng mã của bạn.',true)})}
